#include <bits/stdc++.h>
using namespace std;
using LL = long long;
constexpr int MOD = 1'000'000'007;

int mod_pow(int base, int exp) {
    int res = 1;
    while (exp > 0) {
        if (exp & 1) res = (LL)res * base % MOD;
        base = (LL)base * base % MOD;
        exp >>= 1;
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<vector<int>> prob(n);
    for (auto &row : prob) {
        row.resize(n);
        for (int &val : row) {
            cin >> val;
            val = (LL)val * mod_pow(100, MOD - 2) % MOD;
        }
    }

    vector<vector<int>> group_sizes(n + 1);
    vector<vector<int>> subset_list(n + 1);
    for (int size = 0; size <= n; ++size) {
        group_sizes[size].resize(1 << n);
        for (int s = 0; s < (1 << n); ++s) {
            if (__builtin_popcount(s) == size) {
                group_sizes[size][s] = subset_list[size].size();
                subset_list[size].push_back(s);
            }
        }
    }

    vector<map<LL, int>> dp(n + 1);
    dp[0][1] = 1;
    for (int i = 1; i <= n; ++i) {
        for (int s = 0; s < (1 << n); ++s) {
            int product_prob = 1;
            for (int j = 0; j < n; ++j) {
                if (s & (1 << j))
                    product_prob = (LL)product_prob * prob[i - 1][j] % MOD;
                else
                    product_prob = (LL)product_prob * (1 + MOD - prob[i - 1][j]) % MOD;
            }
            for (auto &[f, count] : dp[i - 1]) {
                LL mask = 0;
                for (int t : subset_list[i]) {
                    for (int j = 0; j < n; ++j) {
                        if ((t >> j & 1) && (s >> j & 1) && (f >> group_sizes[i - 1][t ^ 1 << j] & 1))
                            { mask |= 1LL << group_sizes[i][t]; break; }
                    }
                }
                dp[i][mask] = (dp[i][mask] + LL(count) * product_prob) % MOD;
            }
        }
    }
    cout << dp[n][1] << "\n";
    return 0;
}
